# updated JS API lines (RU, EN)
API2={
"Tabs":("PsyScripts.Tabs.init(root, opts), .get(el) → {go(i), next(), prev(), index, destroy()}; событие tabs:change","PsyScripts.Tabs.init(root, opts), .get(el) → {go(i), next(), prev(), index, destroy()}; event tabs:change"),
"ThemeSwitcher":("PsyScripts.Theme.set('dark'), .toggle(), .get(), .list(), .clear(); кнопки data-theme-set=\"имя\"; событие theme:change","PsyScripts.Theme.set('dark'), .toggle(), .get(), .list(), .clear(); buttons data-theme-set=\"name\"; event theme:change"),
"Toast":("PsyScripts.Toast.show('Text', {type, position, duration, title, action:{label,onClick}}), .success()/.error()/.info()/.warning(), .dismiss(el), .clear()","PsyScripts.Toast.show('Text', {type, position, duration, title, action:{label,onClick}}), .success()/.error()/.info()/.warning(), .dismiss(el), .clear()"),
"Modal":("PsyScripts.Modal.open(id|el, opts), .close(el), .toggle(), .closeAll(), .confirm({title,text}) → Promise&lt;boolean&gt;","PsyScripts.Modal.open(id|el, opts), .close(el), .toggle(), .closeAll(), .confirm({title,text}) → Promise&lt;boolean&gt;"),
"Carousel":("PsyScripts.Carousel.init(root, opts), .get(el) → {go(i), next(), prev(), play(), pause(), refresh(), destroy()}","PsyScripts.Carousel.init(root, opts), .get(el) → {go(i), next(), prev(), play(), pause(), refresh(), destroy()}"),
"Accordion":("PsyScripts.Accordion.open(item), .close(), .toggle(), .openAll(root), .closeAll(root)","PsyScripts.Accordion.open(item), .close(), .toggle(), .openAll(root), .closeAll(root)"),
"Counter":("PsyScripts.Counter.set(el, value, {duration, easing}), .run(el); свои кривые: PsyScripts.Counter.easings.name = t =&gt; …","PsyScripts.Counter.set(el, value, {duration, easing}), .run(el); custom curves: PsyScripts.Counter.easings.name = t =&gt; …"),
"FormValidation":("PsyScripts.Form.validate(form), .check(field), .reset(form), .serialize(form), .addRule('name', (value, field) =&gt; true | false | 'message', 'Default message')","PsyScripts.Form.validate(form), .check(field), .reset(form), .serialize(form), .addRule('name', (value, field) =&gt; true | false | 'message', 'Default message')"),
"CookieBanner":("PsyScripts.Cookie.get(), .has('analytics'), .accept(), .decline(), .save('custom', {analytics:true}), .show(), .reset(); событие psy:cookie","PsyScripts.Cookie.get(), .has('analytics'), .accept(), .decline(), .save('custom', {analytics:true}), .show(), .reset(); event psy:cookie"),
"Tooltip":("PsyScripts.Tooltip.show(el), .hide(), .set(el, text). Esc и прокрутка скрывают подсказку.","PsyScripts.Tooltip.show(el), .hide(), .set(el, text). Esc and scrolling hide the tooltip."),
"ImageLightbox":("PsyScripts.Lightbox.open(imgList, index), .close(), .next(), .prev()","PsyScripts.Lightbox.open(imgList, index), .close(), .next(), .prev()"),
"I18n":("PsyScripts.I18n.t(key, vars), .setLang('en'), .lang, .langs, .has(key), .add(lang, dict), .apply(root), .number(n); событие psy:lang","PsyScripts.I18n.t(key, vars), .setLang('en'), .lang, .langs, .has(key), .add(lang, dict), .apply(root), .number(n); event psy:lang"),
}
_D=[]
for n,d,a,ex,api in D:
    if n in API2: api=API2[n][0]
    _D.append((n,d,a,ex,api))
D[:]=_D
for n,(ru,en) in API2.items():
    ed,ea,_=EN[n]; EN[n]=(ed,ea,en)

